(function() {
    'use strict';

    class CRECEAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'CRECE: Working Capital Crunch';
            this.version = '1.1.0';
            this.REVENUE_SCHEDULE = [
                { base: 3500, maxmart: 500 },
                { base: 3500, maxmart: 1000 },
                { base: 3500, maxmart: 1500 },
                { base: 3500, maxmart: 1500 },
                { base: 3500, maxmart: 1500 },
                { base: 3500, maxmart: 1500 },
                { base: 3500, maxmart: 1500 },
                { base: 3600, maxmart: 1500 },
                { base: 3600, maxmart: 1500 },
                { base: 3700, maxmart: 1500 },
                { base: 3700, maxmart: 1500 },
                { base: 3800, maxmart: 1500 }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 1200,
                    accountsReceivable: 5800,
                    inventory: 3100,
                    accountsPayable: 3400,
                    creditLineUsed: 2975,
                    creditLineLimit: 3500,
                    creditAvailable: 525,
                    dso: 50,
                    dio: 27,
                    dpo: 30,
                    ccc: 47,
                    supplierRelationship: 75,
                    customerRelationship: 80,
                    currentRatio: 1.59,
                    totalFinancingCost: 0,
                    totalRevenue: 0,
                    totalProfit: 0,
                    cashHistory: [],
                    cccHistory: [],
                    profitHistory: [],
                    revenueHistory: [],
                    financingCostHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    collectionEffort: 5,
                    paymentDays: 30,
                    inventoryDays: 27,
                    factoringPct: 0
                };
            }
        }

        validateDecisions(decisions) {
            var ce = document.getElementById('collectionEffortInput');
            if (ce) decisions.collectionEffort = parseInt(ce.value);

            var pd = document.getElementById('paymentDaysInput');
            if (pd) decisions.paymentDays = parseInt(pd.value);

            var invd = document.getElementById('inventoryDaysInput');
            if (invd) decisions.inventoryDays = parseInt(invd.value);

            var fp = document.getElementById('factoringPctInput');
            if (fp) decisions.factoringPct = parseInt(fp.value);

            if (!decisions.collectionEffort || decisions.collectionEffort < 1 || decisions.collectionEffort > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('collection_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.paymentDays || decisions.paymentDays < 15 || decisions.paymentDays > 60) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('payment_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.inventoryDays || decisions.inventoryDays < 15 || decisions.inventoryDays > 45) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('inventory_warning'), 'warning'
                );
                return false;
            }
            if (decisions.factoringPct < 0 || decisions.factoringPct > 100 || isNaN(decisions.factoringPct)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('factoring_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var idx = Math.min(period - 1, this.REVENUE_SCHEDULE.length - 1);
            var revSchedule = this.REVENUE_SCHEDULE[idx];

            var revenue = revSchedule.base + revSchedule.maxmart;
            var cogs = Math.round(revenue * 0.815);
            var opex = 420;
            var grossProfit = revenue - cogs;

            var baseDSO = 50;
            var dsoShift = (d.collectionEffort - 5) * 3;
            var newDSO = Math.max(25, Math.min(65, baseDSO - dsoShift));
            var newDPO = d.paymentDays;
            var newDIO = d.inventoryDays;
            var newCCC = newDIO + newDSO - newDPO;

            var collectionRate = Math.min(1, 30 / Math.max(newDSO, 1));
            var collections = Math.round(ds.accountsReceivable * collectionRate);

            var factoredAmount = Math.round((ds.accountsReceivable - collections) * (d.factoringPct / 100));
            var factoringFee = Math.round(factoredAmount * 0.03);
            var factoringCash = factoredAmount - factoringFee;

            var newAR = Math.max(0, ds.accountsReceivable - collections - factoredAmount + revenue);

            var paymentRate = Math.min(1, 30 / Math.max(newDPO, 1));
            var supplierPayments = Math.round(ds.accountsPayable * paymentRate);
            var newAP = Math.max(0, ds.accountsPayable - supplierPayments + cogs);

            var dailyCOGS = cogs / 30;
            var targetInventory = Math.round(dailyCOGS * newDIO);
            var goodsSold = Math.round(cogs * 0.85);
            var inventoryNeeded = Math.max(0, targetInventory - ds.inventory + goodsSold);
            var newInventory = Math.max(0, ds.inventory + inventoryNeeded - goodsSold);

            var fillRate = targetInventory > 0 ? Math.min(100, Math.round((newInventory / targetInventory) * 100)) : 100;
            if (fillRate < 97) {
                var penalty = fillRate / 100;
                revenue = Math.round(revenue * penalty);
                grossProfit = revenue - cogs;
            }

            var creditLimit = period >= 4 ? 6000 : 3500;
            var creditInterest = Math.round(ds.creditLineUsed * 0.015);
            var periodFinancingCost = factoringFee + creditInterest;
            var profit = grossProfit - opex - periodFinancingCost;

            var netCashFlow = collections + factoringCash - supplierPayments - inventoryNeeded - opex - creditInterest;
            var newCash = ds.cash + netCashFlow;

            var creditDraw = 0;
            if (newCash < 0 && ds.creditLineUsed < creditLimit) {
                creditDraw = Math.min(Math.abs(newCash) + 200, creditLimit - ds.creditLineUsed);
                newCash += creditDraw;
            }
            var newCreditUsed = ds.creditLineUsed + creditDraw;

            if (newCash > 1500 && newCreditUsed > 0) {
                var repay = Math.min(newCash - 1000, newCreditUsed);
                newCash -= repay;
                newCreditUsed -= repay;
            }

            var supplierDelta = 0;
            if (newDPO > 50) supplierDelta = -4;
            else if (newDPO > 45) supplierDelta = -2;
            else if (newDPO > 35) supplierDelta = -1;
            else if (newDPO <= 30) supplierDelta = 1;
            var newSupplierRel = Math.max(0, Math.min(100, ds.supplierRelationship + supplierDelta));

            var customerDelta = 0;
            if (d.collectionEffort >= 9) customerDelta = -3;
            else if (d.collectionEffort >= 7) customerDelta = -1;
            else if (d.collectionEffort <= 3) customerDelta = 1;
            var newCustomerRel = Math.max(0, Math.min(100, ds.customerRelationship + customerDelta));

            var currentAssets = Math.max(0, newCash) + newAR + newInventory;
            var currentLiabilities = newAP + newCreditUsed;
            var currentRatio = currentLiabilities > 0 ? Math.round((currentAssets / currentLiabilities) * 100) / 100 : 9.99;

            ds.cash = Math.round(newCash);
            ds.accountsReceivable = Math.round(newAR);
            ds.inventory = Math.round(newInventory);
            ds.accountsPayable = Math.round(newAP);
            ds.creditLineUsed = Math.round(newCreditUsed);
            ds.creditLineLimit = creditLimit;
            ds.creditAvailable = creditLimit - ds.creditLineUsed;
            ds.dso = Math.round(newDSO);
            ds.dio = Math.round(newDIO);
            ds.dpo = Math.round(newDPO);
            ds.ccc = Math.round(newCCC);
            ds.supplierRelationship = Math.round(newSupplierRel);
            ds.customerRelationship = Math.round(newCustomerRel);
            ds.currentRatio = currentRatio;
            ds.totalFinancingCost += periodFinancingCost;
            ds.totalRevenue += revenue;
            ds.totalProfit += profit;

            ds.cashHistory.push(ds.cash);
            ds.cccHistory.push(ds.ccc);
            ds.profitHistory.push(Math.round(profit));
            ds.revenueHistory.push(revenue);
            ds.financingCostHistory.push(periodFinancingCost);

            return {
                period: period,
                revenue: revenue,
                cogs: cogs,
                grossProfit: grossProfit,
                profit: Math.round(profit),
                collections: collections,
                factoringCash: factoringCash,
                factoringFee: factoringFee,
                creditInterest: creditInterest,
                financingCost: periodFinancingCost,
                netCashFlow: Math.round(netCashFlow),
                cash: ds.cash,
                ccc: ds.ccc,
                dso: ds.dso,
                dio: ds.dio,
                dpo: ds.dpo,
                currentRatio: currentRatio,
                supplierRelationship: ds.supplierRelationship,
                customerRelationship: ds.customerRelationship,
                fillRate: fillRate,
                creditAvailable: creditLimit - ds.creditLineUsed
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) { return '$' + Math.round(v).toLocaleString(); });
            uiManager.bind('cccDisplay', 'domainState.ccc', function(v) { return v + ' d'; });
            uiManager.bind('creditDisplay', 'domainState.creditAvailable', function(v) {
                return '$' + Math.round(v).toLocaleString();
            });
            uiManager.bind('ratioDisplay', 'domainState.currentRatio', function(v) { return v.toFixed(2) + 'x'; });
            uiManager.bind('supplierDisplay', 'domainState.supplierRelationship', function(v) { return v + '/100'; });
            uiManager.bind('customerDisplay', 'domainState.customerRelationship', function(v) { return v + '/100'; });
            uiManager.bind('dsoDisplay', 'domainState.dso');
            uiManager.bind('dioDisplay', 'domainState.dio');
            uiManager.bind('dpoDisplay', 'domainState.dpo');
            uiManager.bind('cccCalcDisplay', 'domainState.ccc');
        }

        getChartConfig() {
            return {
                cashChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Cash Balance (000 MXN)',
                            data: [],
                            borderColor: '#27ae60',
                            backgroundColor: 'rgba(39,174,96,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cash Balance Over Time' }
                        },
                        scales: { y: { beginAtZero: false } }
                    }
                },
                cccChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'CCC (days)',
                            data: [],
                            borderColor: '#e67e22',
                            backgroundColor: 'rgba(230,126,34,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Cash Conversion Cycle' }
                        },
                        scales: { y: { beginAtZero: false } }
                    }
                }
            };
        }

        getChartData(state) {
            var cashLabels = state.domainState.cashHistory.map(function(_, i) { return 'M' + (i + 1); });
            var cccLabels = state.domainState.cccHistory.map(function(_, i) { return 'M' + (i + 1); });
            return {
                cashChart: {
                    labels: cashLabels,
                    datasets: [{ data: state.domainState.cashHistory }]
                },
                cccChart: {
                    labels: cccLabels,
                    datasets: [{ data: state.domainState.cccHistory }]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.cash < 0) return window.mySimulation.t('hint_cash_negative');
            if (results.cash < 500) return window.mySimulation.t('hint_cash_low');
            if (results.ccc > 55) return window.mySimulation.t('hint_ccc_high');
            if (results.currentRatio < 1.15) return window.mySimulation.t('hint_covenant');
            if (results.supplierRelationship < 50) return window.mySimulation.t('hint_supplier_risk');
            if (state.decisions.factoringPct > 50) return window.mySimulation.t('hint_factoring_expensive');
            if (results.profit > 0 && results.ccc < 40) return window.mySimulation.t('hint_good');
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.revenue', label: 'Revenue', i18nKey: 'col_revenue', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.profit', label: 'Profit', i18nKey: 'col_profit', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.cash', label: 'Cash', i18nKey: 'col_cash', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.ccc', label: 'CCC', i18nKey: 'col_ccc', formatter: function(v) { return v + 'd'; } },
                { key: 'results.financingCost', label: 'Financing Cost', i18nKey: 'col_financing', formatter: function(v) { return '$' + v.toLocaleString(); } },
                { key: 'results.currentRatio', label: 'Current Ratio', i18nKey: 'col_ratio', formatter: function(v) { return v.toFixed(2) + 'x'; } }
            ];
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var finalCash = history[history.length - 1].results ? history[history.length - 1].results.cash : 0;
            var finalCCC = history[history.length - 1].results ? history[history.length - 1].results.ccc : 47;
            var cccImprovement = 47 - finalCCC;

            var totalFinancing = 0;
            var totalRatio = 0;
            var totalSupplier = 0;
            var totalCustomer = 0;
            for (var i = 0; i < history.length; i++) {
                var r = history[i].results || {};
                totalFinancing += r.financingCost || 0;
                totalRatio += r.currentRatio || 0;
                totalSupplier += r.supplierRelationship || 0;
                totalCustomer += r.customerRelationship || 0;
            }
            var avgRatio = totalRatio / history.length;
            var avgRelationship = (totalSupplier + totalCustomer) / (history.length * 2);

            var cashScore = Math.min(100, Math.max(0, (finalCash / 50)));
            var cccScore = Math.min(100, Math.max(0, cccImprovement * 5));
            var finScore = Math.min(100, Math.max(0, 100 - (totalFinancing / 50)));
            var ratioScore = Math.min(100, Math.max(0, (avgRatio - 1) * 100));
            var relScore = avgRelationship;

            var wcms = Math.round(cashScore * 0.3 + cccScore * 0.25 + finScore * 0.2 + ratioScore * 0.15 + relScore * 0.1);

            var performance = 'Beginner';
            if (wcms >= 70) performance = 'Excellent';
            else if (wcms >= 50) performance = 'Good';
            else if (wcms >= 30) performance = 'Developing';

            var insights = [];
            if (cccImprovement >= 15) insights.push('Outstanding CCC reduction — freed significant permanent cash.');
            else if (cccImprovement >= 5) insights.push('Solid CCC improvement — working capital discipline is developing.');
            else insights.push('CCC barely improved — consider more aggressive receivables and inventory optimization.');

            if (totalFinancing < 1500) insights.push('Low financing costs — efficient use of credit instruments.');
            else if (totalFinancing > 3000) insights.push('High financing costs — over-reliance on expensive instruments like factoring.');

            if (avgRatio >= 1.3) insights.push('Strong covenant compliance throughout the simulation.');
            else if (avgRatio < 1.15) insights.push('Covenant compliance was precarious — bank relationship at risk.');

            return {
                wcms: wcms,
                finalCash: finalCash,
                cccImprovement: cccImprovement,
                totalFinancingCost: totalFinancing,
                avgCurrentRatio: Math.round(avgRatio * 100) / 100,
                avgRelationship: Math.round(avgRelationship),
                performance: performance,
                insights: insights
            };
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:               `CRECE: Working Capital Crunch`,
                    subtitle:            `Cash Flow Management for Growth`,
                    period_label:        `Month`,
                    period_of:           `of`,
                    briefing_title:      `Situation Briefing`,
                    briefing_text:       `You lead CRECE Distribuciones, a growing consumer goods distributor that just secured a transformational contract with MAXMART. Revenue will increase 43%, but your working capital cannot sustain the growth. Manage collections, payments, inventory, and financing to survive the cash crunch.`,
                    cash_label:          `Cash (000 MXN)`,
                    ccc_label:           `CCC (days)`,
                    credit_label:        `Credit Available (000)`,
                    ratio_label:         `Current Ratio`,
                    supplier_label:      `Supplier Relationship`,
                    customer_label:      `Customer Relationship`,
                    ccc_detail_title:    `CCC Breakdown`,
                    dso_label:           `DSO`,
                    dio_label:           `DIO`,
                    dpo_label:           `DPO`,
                    ccc_equals:          `CCC`,
                    days_label:          `days`,
                    decisions_heading:   `Period Decisions`,
                    collection_label:    `Collection Effort (1-10)`,
                    collection_hint:     `Higher = lower DSO, but may hurt customer relationships`,
                    payment_label:       `Supplier Payment Target (15-60 days)`,
                    payment_hint:        `Higher = preserves cash, but strains supplier relationships`,
                    inventory_label:     `Target Inventory (15-45 days)`,
                    inventory_hint:      `Lower = frees cash, but risks stockouts below 97% fill rate`,
                    factoring_label:     `Receivables Factoring (0-100%)`,
                    factoring_hint:      `Immediate cash at 3% monthly cost per factored amount`,
                    submit_btn:          `Submit Month`,
                    undo_btn:            `Undo Last Month`,
                    history_title:       `Period History`,
                    collection_warning:  `Collection effort must be between 1 and 10`,
                    payment_warning:     `Payment days must be between 15 and 60`,
                    inventory_warning:   `Inventory days must be between 15 and 45`,
                    factoring_warning:   `Factoring percentage must be between 0 and 100`,
                    hint_cash_negative:  `CRITICAL: Cash balance is negative! Draw on credit line or increase factoring immediately.`,
                    hint_cash_low:       `Warning: Cash is dangerously low. Consider factoring receivables or extending supplier payments.`,
                    hint_ccc_high:       `Your CCC exceeds 55 days. Look for ways to reduce DSO or DIO, or extend DPO.`,
                    hint_covenant:       `Current ratio is below the 1.15x bank covenant! Reduce liabilities or increase current assets.`,
                    hint_supplier_risk:  `Supplier relationships are deteriorating. Consider paying closer to agreed terms.`,
                    hint_factoring_expensive: `You are factoring over 50% of receivables. This is very expensive — consider alternatives.`,
                    hint_good:           `Good performance! Positive profit and healthy CCC. Keep optimizing.`,
                    col_revenue:         `Revenue`,
                    col_profit:          `Profit`,
                    col_cash:            `Cash`,
                    col_ccc:             `CCC`,
                    col_financing:       `Financing Cost`,
                    col_ratio:           `Current Ratio`
                },
                es: {
                    title:               `CRECE: Crisis de Capital de Trabajo`,
                    subtitle:            `Gestion de Flujo de Efectivo para el Crecimiento`,
                    period_label:        `Mes`,
